import { defineConfig, devices } from "@playwright/test";
import { defineBddConfig } from "playwright-bdd";
import rootConfig from "./playwright.config.ts";

/**
 * BDD golden-path suite: the same webServer boot and browser setup as the
 * regular e2e suite, but its tests are generated by bddgen from the Gherkin
 * features (e2e/features) + step definitions (e2e/steps). Generated output
 * (`.features-gen/`) is gitignored; both commands run THIS config:
 *
 *   pnpm -C apps/web e2e:bdd
 *   # -> bddgen -c playwright-bdd.config.ts && playwright test --config=playwright-bdd.config.ts
 */
const bddTestDir = defineBddConfig({
  featuresRoot: "./e2e/features",
  // step definition files (string or glob — directories are not implied)
  steps: "./e2e/steps/**/*.ts",
  outputDir: ".features-gen",
});

export default defineConfig({
  ...rootConfig,
  testDir: bddTestDir,
  reporter: [["list"]],
  use: {
    ...rootConfig.use,
  },
  projects: [{ name: "desktop-chrome", use: { ...devices["Desktop Chrome"] } }],
});
